class Solution:
    def findNumbers(self, nums: list[int]) -> int:
        return sum(1 for x in nums if len(str(x)) % 2 == 0)

#include <vector>
#include <string>

class Solution {
public:
    int findNumbers(std::vector<int>& nums) {
        int count = 0;
        for (int x : nums) {
            if (std::to_string(x).size() % 2 == 0) count++;
        }
        return count;
    }
};

class Solution {
    public int findNumbers(int[] nums) {
        int count = 0;
        for (int x : nums) {
            if (String.valueOf(x).length() % 2 == 0) count++;
        }
        return count;
    }
}

var findNumbers = function(nums) {
    let count = 0;
    for (const x of nums) {
        if (String(x).length % 2 === 0) count++;
    }
    return count;
};
